     1→# ABOUTME: Sea of Nodes IR graph container for Chalk compiler
     2→# ABOUTME: Manages collection of IR nodes and provides JSON serialization for IR persistence
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Graph {
     8→    use Chalk::IR::Node;
     9→
    10→    field $nodes :reader;
    11→    field $entry :reader;
    12→
    13→    ADJUST {
    14→        $nodes = {};
    15→        $entry = undef;
    16→    }
    17→
    18→    method add_node($node) {
    19→        my $node_id = $node->id;
    20→        $nodes->{$node_id} = $node;
    21→
    22→        # First node added becomes entry point
    23→        $entry //= $node_id;
    24→
    25→        return;
    26→    }
    27→
    28→    method get_node($id) {
    29→        return $nodes->{$id};
    30→    }
    31→
    32→    method node_count() {
    33→        return scalar keys $nodes->%*;
    34→    }
    35→
    36→    method set_entry($new_entry) {
    37→        $entry = $new_entry;
    38→        return;
    39→    }
    40→
    41→    method to_json() {
    42→        my @node_list = map { $_->to_hash() } values $nodes->%*;
    43→
    44→        return {
    45→            version => '1.0',
    46→            entry   => $entry,
    47→            nodes   => \@node_list,
    48→        };
    49→    }
    50→
    51→    sub from_json( $class, $json ) {
    52→        my $graph = $class->new();
    53→
    54→        # Restore nodes in order
    55→        for my $node_data ( $json->{nodes}->@* ) {
    56→            my $node = Chalk::IR::Node->new(
    57→                id         => $node_data->{id},
    58→                op         => $node_data->{op},
    59→                inputs     => $node_data->{inputs},
    60→                attributes => $node_data->{attributes},
    61→            );
    62→            $graph->add_node($node);
    63→        }
    64→
    65→        # Set entry explicitly (in case it's not the first node)
    66→        $graph->set_entry( $json->{entry} );
    67→
    68→        return $graph;
    69→    }
    70→}
    71→
    72→1;
    73→

